import http from 'k6/http';
import { check } from 'k6';

// Breakpoint test, open model: drive an arrival rate, not a user count,
// so the generator does not throttle itself as latency rises.
export const options = {
  scenarios: {
    breakpoint: {
      executor: 'ramping-arrival-rate',
      startRate: 100, timeUnit: '1s',
      preAllocatedVUs: 200, maxVUs: 2000,
      stages: [{ duration: '10m', target: 1200 }],   // one instance: ramp past the expected knee
    },
  },
  thresholds: { http_req_duration: ['p(99)<300'] },     // the knee is where this stops holding
};

export default function () {
  const res = http.post('https://checkout.example.test/orders',
    JSON.stringify({ sku: 'A1', qty: 1 }), { headers: { 'Content-Type': 'application/json' } });
  check(res, { 'status 2xx': r => r.status >= 200 && r.status < 300 });
}
